starter.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long chap = 0, ong = 1000000;
        while (chap < ong) {
            long orta = (chap + ong + 1) / 2;
            if (orta * orta * orta < n) chap = orta;
            else ong = orta - 1;
        }
        System.out.println(chap);
    }
}

